        return (0.0, 0.0)

    def dist(a, b):
        if dist_matrix is not None:
            return dist_matrix[a][b]
        pa = point(a)
        pb = point(b)
        dx = pa[0] - pb[0]
        dy = pa[1] - pb[1]
        return (dx * dx + dy * dy) ** 0.5

    def route_load(route):
        s = 0
        for c in route:
            s += demand_of(c)
        return s

    def route_cost(route):
        if not route:
            return 0.0
        cost = dist(depot, route[0])
        for i in range(len(route) - 1):
            cost += dist(route[i], route[i + 1])
        cost += dist(route[-1], depot)
        return cost

    def insert_delta(route, c, pos):
        prev = depot if pos == 0 else route[pos - 1]
        nxt = depot if pos == len(route) else route[pos]
        return dist(prev, c) + dist(c, nxt) - dist(prev, nxt)

    def remove_delta(route, idx):
        c = route[idx]
        prev = depot if idx == 0 else route[idx - 1]
        nxt = depot if idx == len(route) - 1 else route[idx + 1]
        return dist(prev, nxt) - dist(prev, c) - dist(c, nxt)

    remaining = list(customers)
    routes = []

    if coords is not None:
        depot_point = point(depot)
        if depot_point is None:
            depot_point = (0.0, 0.0)

        def angle_key(c):
            p = point(c)
            dx = p[0] - depot_point[0]
            dy = p[1] - depot_point[1]
            ang = 0.0
            if dx >= 0 and dy >= 0:
                ang = 0.0 + dy / (abs(dx) + abs(dy) + 1e-12)
            elif dx < 0 <= dy:
                ang = 1.0 + abs(dx) / (abs(dx) + abs(dy) + 1e-12)
            elif dx < 0 and dy < 0:
                ang = 2.0 + abs(dy) / (abs(dx) + abs(dy) + 1e-12)
            else:
                ang = 3.0 + abs(dx) / (abs(dx) + abs(dy) + 1e-12)
            return (ang, dist(depot, c), c)

        ordered = sorted(remaining, key=angle_key)
        cur = []
        load = 0
        for c in ordered:
            d = demand_of(c)
            if cur and load + d > capacity:
                routes.append(cur)
                cur = [c]
                load = d
            else:
                cur.append(c)
                load += d
        if cur:
            routes.append(cur)
    else:
        unserved = set(remaining)
        while unserved:
            start = None
            best = None
            for c in unserved:
                key = (-dist(depot, c), c)
                if best is None or key < best:
                    best = key
                    start = c
            route = [start]
            load = demand_of(start)
            unserved.remove(start)
            while True:
                last = route[-1]
                cand = None
                cand_key = None
                for c in unserved:
                    d = demand_of(c)
                    if load + d > capacity:
                        continue
                    key = (dist(last, c), d, c)
                    if cand_key is None or key < cand_key:
                        cand_key = key
                        cand = c
                if cand is None:
                    break
                route.append(cand)
                load += demand_of(cand)
                unserved.remove(cand)
            routes.append(route)

    def two_opt(route):
        n = len(route)
        if n < 4:
            return route[:]
        best = route[:]
        best_cost = route_cost(best)
        improved = True
        while improved:
            improved = False
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    c = route_cost(cand)
                    if c + 1e-12 < best_cost:
                        best = cand
                        best_cost = c
                        improved = True
                        break
                if improved:
                    break
        return best

    routes = [two_opt(r) for r in routes if r]

    changed = True
    while changed:
        changed = False
        loads = [route_load(r) for r in routes]
        for i in range(len(routes)):
            if not routes[i]:
                continue
            for idx in range(len(routes[i])):
                c = routes[i][idx]
                dc = demand_of(c)
                best_move = None
                best_total = 0.0
                rem = remove_delta(routes[i], idx)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    if loads[j] + dc > capacity:
                        continue
                    for pos in range(len(routes[j]) + 1):
                        total = rem + insert_delta(routes[j], c, pos)
                        if total < best_total:
                            best_total = total
                            best_move = (j, pos)
                if best_move is not None:
                    j, pos = best_move
                    routes[j].insert(pos, c)
                    loads[j] += dc
                    loads[i] -= dc
                    routes[i].pop(idx)
                    changed = True
                    break
            if changed:
                break

    routes = [two_opt(r) for r in routes if r]

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in customers if c not in seen]
    if missing:
        for c in missing:
            best_r = None
            best_pos = None
            best_delta = None
            for ri, r in enumerate(routes):
                if route_load(r) + demand_of(c) > capacity:
                    continue
                for pos in range(len(r) + 1):
                    delta = insert_delta(r, c, pos)
                    if best_delta is None or delta < best_delta:
                        best_delta = delta
                        best_r = ri
                        best_pos = pos
            if best_r is None:
                routes.append([c])
            else:
                routes[best_r].insert(best_pos, c)

    cleaned = []
    for r in routes:
        if r:
            cleaned.append(r)
    return cleaned
